                R(ref s, "With Kazuma, <E145 3 88><E149 3 8 1><E003 8>Susato-san <E003 10>and Mr Sholmes all gently<E169 19 3>\r\npushing me in that direction.", "Avec Kazuma, <E145 3 88><E149 3 8 1><E003 8>Susato-san <E003 10>et M. Sholmes me guidant doucement<E169 19 3>\ndans cette direction.");
                R(ref s, "I spent the best part of a year <E169 3 3>immersed in this world,<E003 15>\r\n<E025 3>but always aware of a seed of doubt inside me.", "J'ai passé la majeure partie de l'année <E169 3 3>plongé dans cet univers,<E003 15>\n<E025 3>mais en portant toujours le poids d'un doute au fond de moi.");
                R(ref s, "Until today.", "Jusqu'à aujourd'hui.");
                R(ref s, "Standing in that courtroom earlier, <E003 10>all doubts vanished\r\nfrom my mind.", "Debout dans ce prétoire tout à l'heure, <E003 10>toutes mes hésitations ont\ndisparu.");
                R(ref s, "I was totally focused.<E003 12> I was sure of my belief in my client,<E003 10>\r\nand I was sure I could see the trial through.", "J'étais pleinement serein.<E003 12> J'avais une confiance absolue en mon client,<E003 10>\net la certitude de mener le procès jusqu'à son dénouement.");
                R(ref s, "And at the end of it, <E003 12>I finally realised.", "Et à la toute fin, <E003 12>j'ai enfin compris.");
                R(ref s, "No one else chose <E006>this path<E005> for me.<E003 14>\r\nI chose it myself.", "Personne n'a tracé <E006>cette route<E005> pour moi.<E003 14>\nC'est moi seul qui l'ai choisie.");
                R(ref s, "The path of <E006>a defence lawyer<E005>, <E049><E003 6>eh?", "La route d'un <E006>avocat de la défense<E005>, <E049><E003 6>n'est-ce pas ?");
                R(ref s, "Yes, <E003 10>that's what I am now.<E003 12> <E025 3>That's what I'll be going back\r\nwith you to Japan as.", "Oui, <E003 10>c'est ce que je suis à présent.<E003 12> <E025 3>C'est en cette qualité que je\nrentrerai au Japon avec vous.");
                R(ref s, "And that's the path I'll be following for the rest of my life.", "Et c'est la voie dans laquelle je marcherai pour le restant de mes jours.");
                R(ref s, "Well, <E049><E003 10>it sounds like you've made quite <E006>a resolution<E005> there.", "Eh bien, <E049><E003 10>voilà une magnifique <E006>résolution<E005>.");
                R(ref s, "I have!", "Oui !");
                R(ref s, "Very well, then.<E049><E003 15><E145 46 71><E149 46 0 0><E117 46 15><E003 10>\r\n<E025 2><E333>I must say, <E049><E003 8>it's extremely welcome news.", "Parfait, alors.<E049><E003 15><E145 46 71><E149 46 0 0><E117 46 15><E003 10>\n<E025 2><E333>Je dois dire <E049><E003 8>que c'est une nouvelle des plus heureuses.");
                R(ref s, "I shall make arrangements for your return first thing\r\ntomorrow.<E049><E003 12> <E025 3>But I don't imagine we'll depart for a few days.", "J'organiserai votre retour dès demain matin.<E049><E003 12> <E025 3>Mais je ne pense pas que nous\npuissions partir avant quelques jours.");
                R(ref s, "Not with the symposium having been cancelled now.<E145 46 64><E149 46 0 0><E118 46 0.9><E003 15>\r\n<E025 3>Such a shame...", "Le symposium ayant été annulé.<E145 46 64><E149 46 0 0><E118 46 0.9><E003 15>\n<E025 3>C'est bien dommage...");
                R(ref s, "Never mind.<E049><E003 10> <E025 2>I'm sure there'll be other opportunities in the\r\nfuture.<E049><E003 14> <E145 46 71><E118 46 0.6><E003 6><E025 3>...Well then, <E049><E003 8><E025 2>I'll bid you good night.", "Qu'à cela ne tienne.<E049><E003 10> <E025 2>Il y aura d'autres occasions à l'avenir,<E049><E003 14>\n<E145 46 71><E118 46 0.6><E003 6><E025 3>j'en suis certain. ... Bien, <E049><E003 8><E025 2>je vous souhaite une bonne nuit.");
                R(ref s, "S-<E003 8>Susato-san...", "S-<E003 8>Susato-san...");
                R(ref s, "I...<E003 12>just wanted to let you know I'm back.", "Je...<E003 12>voulais simplement vous avertir de mon retour.");
                return s;
            };

            // [50] _sce04_c500_0050_eng#2
            entryTranslators["BB\\script\\output\\_sce04_c500_0050_eng#2"] = (en) => {
                string s = en;
                R(ref s, "Did you, <E003 10><E025 4>um...", "Avez-vous, <E003 10><E025 4>euh...");
                R(ref s, "...hear what your father and I were discussing?", "... entendu notre échange avec votre père ?");
                R(ref s, "I'm sorry, <E049><E003 8>I did, <E049><E003 8>yes.<E049><E003 10> <E025 3>I...<E049><E003 12>couldn't help <E049><E003 10>but...", "Pardonnez-moi, <E049><E003 8>oui, <E049><E003 8>en effet.<E049><E003 10> <E025 3>Je n'ai...<E049><E003 12>pas pu m'empêcher de...");
                R(ref s, "Oh!<E003 16> <E025 2><E239>...How much did you hear?", "Oh !<E003 16> <E025 2><E239>... Qu'avez-vous entendu ?");
