                R(ref s, "...In other words, <E049><E003 8>from <E145 3 64><E118 3 0.9>the beginning.", "... Autrement dit, <E049><E003 8>depuis <E145 3 64><E118 3 0.9>le début.");
                R(ref s, "So you've made up your mind.", "Vous avez donc pris votre décision.");
                R(ref s, "You'll <E006>return to Japan<E005> and continue working as a defence\r\nlawyer.", "Vous <E006>rentrez au Japon<E005> pour y exercer comme avocat de la\ndéfense.");
                R(ref s, "Ah...<E003 16>yes.<E003 8> I'm, <E003 10><E342>I'm sorry.<E003 12> <E025 2>I really should have consulted you\r\nabout it.", "Ah...<E003 16>oui.<E003 8> Je, <E003 10><E342>je suis désolé.<E003 12> <E025 2>J'aurais vraiment dû vous en parler\nauparavant.");
                R(ref s, "I did want to earlier this evening, <E003 8><E025 3>actually.<E003 14>\r\n<E025 2>But you'd already gone out.", "C'était mon intention plus tôt ce soir, <E003 8><E025 3>à vrai dire.<E003 14>\n<E025 2>Mais vous étiez déjà partie.");
                R(ref s, "Oh no, <E049><E003 12><E025 3>that's quite alright.", "Oh non, <E049><E003 12><E025 3>ne vous en faites pas.");
                R(ref s, "I already knew that it's what you'd decide, <E049><E003 8>Naruhodo-san.", "Je savais d'avance ce que vous décideriez, <E049><E003 8>Naruhodo-san.");
                R(ref s, "You did?!", "Vraiment ?!");
                R(ref s, "Um...<E003 14><E025 3>Susato-san...", "Euh...<E003 14><E025 3>Susato-san...");
                R(ref s, "Ah!<E049><E003 18> <E025 2><E341>...Yes?", "Ah !<E049><E003 18> <E025 2><E341>... Oui ?");
                R(ref s, "I suppose this means it...<E003 20><E333><E025 3>has to be farewell soon.", "J'imagine que cela signifie que...<E003 20><E333><E025 3>nos adieux approchent.");
                R(ref s, "I suppose...", "J'imagine...");
                R(ref s, "You'll be a great help to Kazuma going forward.", "Vous serez d'un précieux secours pour Kazuma désormais.");
                R(ref s, "I mean, <E003 8>I know he's a brilliant lawyer, <E003 10><E025 3>but he's new to the\r\nBritish courtroom.", "Je sais bien qu'il est un brillant juriste, <E003 10><E025 3>mais il découvre encore\nles tribunaux britanniques.");
                R(ref s, "He'll certainly benefit greatly having a brilliant judicial\r\nassistant at his side.", "Il aura grand profit à compter sur une assistante juridique aussi\nremarquable à ses côtés.");
                R(ref s, "...I'll do my very best.", "... Je ferai de mon mieux.");
                R(ref s, "(I wish I could say it, <E003 10>but I just can't.)", "(J'aimerais tant lui demander, <E003 10>mais je n'y parviens pas.)");
                R(ref s, "(I can't ask her to come with me.<E003 20>\r\n<E025 3>After all<E145 3 82><E149 3 2 1><E117 3 30>...)", "(Je ne peux décemment pas lui demander de me suivre.<E003 20>\n<E025 3>Après tout<E145 3 82><E149 3 2 1><E117 3 30>...)");
