                R(ref s, "...It's growing late.", "... Il se fait tard.");
                R(ref s, "We should both try to get some sleep.<E049><E003 15><E117 3 20><E172 3 -15 130 20 2 0><E492 3 130 20 2><E145 3 83><E149 3 2 1><E003 10>\r\n<E025 3>I'm sure you must be exhausted after today.", "Nous devrions prendre du repos.<E049><E003 15><E117 3 20><E172 3 -15 130 20 2 0><E492 3 130 20 2><E145 3 83><E149 3 2 1><E003 10>\n<E025 3>Vous devez être harassé après une telle journée.");
                R(ref s, "Oh, <E003 12><E025 3>yes...<E003 16>you're right.", "Oh, <E003 12><E025 3>oui...<E003 16>vous avez raison.");
                R(ref s, "Before I retire, <E049><E003 10>let me just say one more time:", "Avant d'aller dormir, <E049><E003 10>laissez-moi vous le redire une dernière fois :");
                R(ref s, "You really were quite splendid in court today.", "Vous avez été véritablement admirable au tribunal aujourd'hui.");
