                string s = en;
                R(ref s, "7th November, 5:42 a.m.\r\n<CNTR><E003 5>Port of Dover, Quayside", "7 novembre, 5 h 42\r\n<CNTR><E003 5>Port de Douvres - Quai d'embarquement");
