                R(ref s, "Such a <E025 5>beautiful <E025 3>morning. <E003 18>\r\n<E042><CNTR><E025 3>Perfect for embarking on a journey, <E003 2><E025 3>isn't <E025 2>it?", "Quelle <E025 5>magnifique <E025 3>matinée. <E003 18>\n<E042><CNTR><E025 3>Idéale pour prendre la mer, <E003 2><E025 3>n'est-ce <E025 2>pas ?");
                R(ref s, "Before I set off...<E003 16><E149 102 1 3><E172 102 5 147 20 3 9><E492 102 147 20 3><E025 2>I'd just like to say how <E003 4><E025 3>thankful\r\n<E042><CNTR>I am <E003 6>for <E025 2>everything <E003 4><E025 3>you've done for me.", "Avant de partir...<E003 16><E149 102 1 3><E172 102 5 147 20 3 9><E492 102 147 20 3><E025 2>je voudrais vous dire à quel point <E003 4><E025 3>je vous suis\n<E042><CNTR>reconnaissant <E003 6>pour <E025 2>tout ce <E003 4><E025 3>que vous avez fait pour moi.");
                R(ref s, "And give my warmest regards <E003 4>to Kazuma, <E003 6><E025 3>please.", "Et transmettez mes salutations les plus sincères <E003 4>à Kazuma, <E003 6><E025 3>je vous prie.");
                R(ref s, "Actually...<E003 16><E025 3>I think you ought to give\r\n<E042><CNTR>him your regards in person, <E003 4><E025 2>don't you?", "À vrai dire...<E003 16><E025 3>je crois que vous devriez les lui\n<E042><CNTR>transmettre en personne, <E003 4><E025 2>vous ne pensez pas ?");
