                R(ref s, "Ryu<E025 3>nosuke<E145 102 77><E149 102 0 1>...", "Ryu<E025 3>nosuke<E145 102 77><E149 102 0 1>...");
                R(ref s, "Kazuma!<E003 18>\r\n<E042><CNTR><E025 3>Wh-<E003 14>What are you <E025 2>doing here?!", "Kazuma !<E003 18>\n<E042><CNTR><E025 3>Q-<E003 14>Qu'est-ce que tu <E025 2>fais là ?!");
                R(ref s, "Ha <E118 103 0.7>ha ha ha hah!", "Ha <E118 103 0.7>ha ha ha ha !");
                R(ref s, "Do you really think I'd miss my best friend's <E025 4>departure?", "Pensais-tu vraiment que je manquerais le départ de mon meilleur <E025 4>ami ?");
                R(ref s, "Thanks.", "Merci.");
                R(ref s, "To be honest, <E003 10>I'd been <E025 2>looking forward <E025 3>to our wild <E003 4>time<E003 8>\r\n<E042><CNTR>tearing up the streets of Her Majesty's capital, <E003 20>but...", "Pour être franc, <E003 10>j'avais <E025 2>hâte de sillonner <E025 3>avec toi <E003 4><E003 8>\n<E042><CNTR>les rues de la capitale de Sa Majesté, <E003 20>mais...");
