                R(ref s, "Oh...<E003 12>I see.", "Oh...<E003 12>je vois.");
                R(ref s, "Actually, <E049><E003 10>Ryunosuke, <E049><E003 30><E145 103 75>I have a favour to ask.", "À vrai dire, <E049><E003 10>Ryunosuke, <E049><E003 30><E145 103 75>j'ai une faveur à te demander.");
