                R(ref s, "<E006>Karuma<E005>?!<E003 24><E025 7> ...<E003 8><E025 3>Why?", "<E006>Karuma<E005> ?!<E003 24><E025 7> ...<E003 8><E025 3>Pourquoi ?");
