                string s = en;
                R(ref s, "I've always known <E025 3>there are demons <E025 4>that live\r\n<E042><CNTR><E025 3>inside people.<E049><E003 30> <E025 3>And now I know there is one in me.", "J'ai toujours su <E025 3>que des démons vivaient <E025 4>au fond\n<E042><CNTR><E025 3>des cœurs.<E049><E003 30> <E025 3>Et je sais qu'il en sommeille un en moi.");
