                R(ref s, "So...<E003 18>that's what you've <E025 2>resolved to do, <E003 6>is it?", "C'est donc...<E003 18>ce que tu as <E025 2>résolu de faire, <E003 6>n'est-ce pas ?");
                R(ref s, "Until I'm ready <E049><E003 16>to face the demon within me – <E049><E003 30>\r\n<E042><CNTR>to slay it once and for all...", "Jusqu'à ce que je sois prêt <E049><E003 16>à affronter ce démon intérieur — <E049><E003 30>\n<E042><CNTR>pour l'abattre une fois pour toutes...");
                R(ref s, "...I leave this <E049><E003 10><E025 4>in your care.<E049><E003 50>\r\n<E042><CNTR><E025 3><E338><E341>If you'll take it.", "... je te confie <E049><E003 10><E025 4>cette lame.<E049><E003 50>\n<E042><CNTR><E025 3><E338><E341>Si tu veux bien l'accepter.");
                R(ref s, "Of course <E025 4>I will.<E003 18>\r\n<E042><CNTR><E025 3>I'll keep it by my side.<E003 20> Always.", "Bien entendu <E025 4>que j'accepte.<E003 18>\n<E042><CNTR><E025 3>Elle restera toujours à mes côtés.<E003 20> Toujours.");
